"""Golden decision table (spec 6.7): >= 200 rows generated by hand-written code (``golden.py``) from 6.5,
compared with ``decide`` row by row."""

from __future__ import annotations

import csv

import golden
import pytest
from policy_factory import (
    AGENT_IDS,
    CFG,
    U,
    context,
    invoice,
    mandate,
    proposal,
    quote_request,
    vault_state,
)

from acb.types import Grade

SKU_BY_UNIT = {10_000: "unit", 200_000: "unit20"}


def _load() -> list[dict[str, str]]:
    with open(golden.GOLDEN_PATH, encoding="ascii", newline="") as fh:
        return list(csv.DictReader(fh))


def test_golden_file_matches_its_hand_written_generator():
    on_disk = golden.GOLDEN_PATH.read_bytes()
    assert on_disk == golden.render(golden.rows()).encode("ascii")
    assert b"\r" not in on_disk
    assert len(_load()) >= 200


def test_golden_covers_every_grade_tier_boundary_action_and_frozen_flag():
    table = _load()
    assert {r["grade"] for r in table} == {"A", "B", "C", "NEW", "NONE", "D"}
    assert {r["tier"] for r in table} == {"0", "1", "2", "3"}
    assert {r["frozen"] for r in table} == {"0", "1"}
    assert {r["action"] for r in table} == {"", "PAY", "PAY_CAPPED", "ESCROW", "REQUEST_OWNER_APPROVAL", "REFUSE"}
    assert {r["outcome"] for r in table} == {"PAY", "PAY_CAPPED", "ESCROW", "NEEDS_OWNER_APPROVAL", "REFUSE"}


def _row_id(row):
    return f"{row['case']}-{row['grade']}-t{row['tier']}-f{row['frozen']}-{row['amount']}-{row['action'] or 'preview'}"


ROWS = _load() if golden.GOLDEN_PATH.exists() else []


@pytest.mark.parametrize("row", ROWS, ids=[_row_id(r) for r in ROWS])
def test_decide_matches_golden_row(row):
    unit = int(row["unit_price"])
    quantity = int(row["quantity"])
    cap_of = row["cap_of"]
    qr = quote_request("test", sku=SKU_BY_UNIT[unit], quantity=quantity, cap_of=cap_of)
    raw = invoice("test", qr=qr, invoice_id=f"inv-{row['case']}", sign=False)  # decide trusts invoice_sig_valid
    superseded = {(AGENT_IDS["test"], cap_of): quantity} if cap_of else None
    ctx = context(
        raw,
        qr,
        grade=Grade[row["grade"]],
        vault=vault_state(tier=int(row["tier"]), frozen=row["frozen"] == "1", balance=100 * U),
        mandate_view=mandate(max_per_tx=50 * U, max_total=500 * U),
        superseded=superseded,
        check_signature=False,
    )
    p = proposal(raw, row["action"]) if row["action"] else None
    from acb.policy import decide

    d = decide(p, ctx, CFG)
    got = {
        "outcome": d.outcome.name,
        "out_amount": str(d.amount),
        "out_quantity": str(d.quantity),
        "requote_quantity": "" if d.requote_quantity is None else str(d.requote_quantity),
        "executable": "1" if d.executable else "0",
        "reasons": ";".join(str(r) for r in d.reasons),
    }
    want = {k: row[k] for k in got}
    assert got == want
